func TestRenderPromConfigGolden(t *testing.T) {
	s := &spec.Specification{
		Name: "golden",
		MasterServers: []*spec.MasterServerSpec{
			{Ip: "10.0.0.1", MetricsPort: 9324},
			{Ip: "10.0.0.2"},
		},
		VolumeServers: []*spec.VolumeServerSpec{
			{Ip: "10.0.0.3"},
		},
		FilerServers: []*spec.FilerServerSpec{
			{Ip: "10.0.0.4", MetricsPort: 9330},
		},
	}

	got := RenderPromConfig(s)

	// Job names are the fixed "seaweedfs-<component>" convention (matching the
	// bundled Grafana dashboard's selectors); the cluster name appears only in
	// the `cluster` label, not the job name.
	want := `scrape_configs:
  - job_name: "seaweedfs-master"
    metrics_path: /metrics
    static_configs:
      - targets:
          - "10.0.0.1:9324"
          - "10.0.0.2:9324"
        labels:
          cluster: "golden"
  - job_name: "seaweedfs-volume"
    metrics_path: /metrics
    static_configs:
      - targets:
          - "10.0.0.3:9324"
        labels:
          cluster: "golden"
  - job_name: "seaweedfs-filer"
    metrics_path: /metrics
    static_configs:
      - targets:
          - "10.0.0.4:9330"
        labels:
          cluster: "golden"
`
	if !strings.HasPrefix(got, want) {
		t.Errorf("RenderPromConfig golden mismatch:\nwant prefix:\n%s\ngot:\n%s", want, got)
	}

	// The node_exporter job is rendered last with a map-ordered target list,
	// so verify its presence and unique hosts rather than exact ordering.
	if !strings.Contains(got, `job_name: "seaweedfs-node-exporter"`) {
		t.Error("missing node-exporter job")
	}
	for _, ip := range []string{"10.0.0.1", "10.0.0.2", "10.0.0.3", "10.0.0.4"} {
		if !strings.Contains(got, ip+":9100") {
			t.Errorf("node_exporter target %s:9100 not found", ip)
		}
	}
}

func TestRenderPromConfigNilReturnsEmpty(t *testing.T) {
	if RenderPromConfig(nil) != "" {
		t.Error("expected empty string for nil spec")
	}
}

// Two volumes co-located on one host must scrape on distinct ports — the
// reconciled per-host-unique assignment, not a single per-component default.
// This is the standalone-render path (no prior deploy-time assignment).
func TestRenderPromConfigCoLocatedDistinctPorts(t *testing.T) {
	s := &spec.Specification{
		VolumeServers: []*spec.VolumeServerSpec{
			{Ip: "10.0.0.9", Port: 8080},
			{Ip: "10.0.0.9", Port: 8081},
		},
	}
	got := RenderPromConfig(s)
	if !strings.Contains(got, "10.0.0.9:9324") || !strings.Contains(got, "10.0.0.9:9325") {
		t.Errorf("expected co-located volumes on distinct ports 9324 and 9325:\n%s", got)
	}
}

func TestNodeExporterUnitContainsPort(t *testing.T) {
	unit := nodeExporterUnit()
	if !strings.Contains(unit, ":9100") {
		t.Error("systemd unit does not expose :9100")
	}
	if !strings.Contains(unit, "ExecStart=/usr/local/bin/node_exporter") {
		t.Error("systemd unit missing ExecStart")
	}
}

// Worker metrics are opt-in; worker hosts must not join the node_exporter job.
func TestRenderPromConfigWorkerTargets(t *testing.T) {
	s := &spec.Specification{
		Name: "golden",
		MasterServers: []*spec.MasterServerSpec{
			{Ip: "10.0.0.1", MetricsPort: 9324},
		},
		WorkerServers: []*spec.WorkerServerSpec{
			{Ip: "10.0.0.71", MetricsPort: 9327, LanceMetricsPort: 9328},
			{Ip: "10.0.0.72"}, // no metrics ports: contributes no targets
		},
	}

	got := RenderPromConfig(s)
	want := `  - job_name: "seaweedfs-worker"
    metrics_path: /metrics
    static_configs:
      - targets:
          - "10.0.0.71:9327"
          - "10.0.0.71:9328"
        labels:
          cluster: "golden"
`
	if !strings.Contains(got, want) {
		t.Errorf("worker job mismatch:\nwant block:\n%s\ngot:\n%s", want, got)
	}
	if strings.Contains(got, "10.0.0.72") {
		t.Error("a worker without metrics ports should contribute no targets")
	}
	if strings.Contains(got, "10.0.0.71:9100") {
		t.Error("worker hosts must not join the node_exporter job")
	}

	s2 := &spec.Specification{
		MasterServers: []*spec.MasterServerSpec{{Ip: "10.0.0.1"}},
		WorkerServers: []*spec.WorkerServerSpec{{Ip: "10.0.0.71"}},
	}
	if strings.Contains(RenderPromConfig(s2), "seaweedfs-worker") {
		t.Error("no worker job expected when no worker exposes metrics")
	}
}

# SeaweedFS seaweed-up Integration Testing Makefile

# Configuration
ifndef DOCKER_COMPOSE
DOCKER_COMPOSE := $(if $(shell command -v docker-compose 2>/dev/null),docker-compose,docker compose)
endif
TEST_TIMEOUT ?= 15m

# Colors for output
BLUE := \033[36m
GREEN := \033[32m
YELLOW := \033[33m
RED := \033[31m
NC := \033[0m # No Color

.PHONY: help build setup test test-single test-multi clean logs status

help: ## Show this help message
	@echo "$(BLUE)seaweed-up Integration Testing$(NC)"
	@echo ""
	@echo "Available targets:"
	@awk 'BEGIN {FS = ":.*?## "} /^[a-zA-Z_-]+:.*?## / {printf "  $(GREEN)%-20s$(NC) %s\n", $$1, $$2}' $(MAKEFILE_LIST)

# Build
build: ## Build seaweed-up binary
	@echo "$(YELLOW)Building seaweed-up...$(NC)"
	@cd ../.. && go build -o seaweed-up .
	@echo "$(GREEN)Build complete!$(NC)"

# Environment Setup
setup: ## Set up test environment (Docker containers)
	@echo "$(YELLOW)Setting up integration test environment...$(NC)"
	@$(DOCKER_COMPOSE) up -d
	@echo "$(BLUE)Waiting for all hosts to be ready...$(NC)"
	@./scripts/wait-for-hosts.sh
	@echo "$(GREEN)Test environment ready!$(NC)"

# Test Targets
test: build ## Run all integration tests
	@echo "$(YELLOW)Running all integration tests...$(NC)"
	@go test -v -tags=integration -timeout=$(TEST_TIMEOUT) ./...

test-single: build setup ## Run single-node deployment test
	@echo "$(YELLOW)Running single-node deployment test...$(NC)"
	@go test -v -tags=integration -timeout=$(TEST_TIMEOUT) -run TestDeploySingleNode ./...

test-multi: build setup ## Run multi-node deployment test
	@echo "$(YELLOW)Running multi-node deployment test...$(NC)"
	@go test -v -tags=integration -timeout=$(TEST_TIMEOUT) -run TestDeployMultiNode ./...

test-destroy: build setup ## Run cluster destroy test
	@echo "$(YELLOW)Running cluster destroy test...$(NC)"
	@go test -v -tags=integration -timeout=$(TEST_TIMEOUT) -run TestClusterDestroy ./...

# Cleanup
clean: ## Clean up test environment
	@echo "$(YELLOW)Cleaning up test environment...$(NC)"
	@$(DOCKER_COMPOSE) down -v --remove-orphans
	@rm -rf .ssh
	@echo "$(GREEN)Environment cleaned up!$(NC)"

# Monitoring and debugging
logs: ## Show logs from all containers
	@$(DOCKER_COMPOSE) logs --tail=50 -f

logs-host1: ## Show logs from host1
	@$(DOCKER_COMPOSE) logs --tail=100 -f target-host-1

logs-host2: ## Show logs from host2
	@$(DOCKER_COMPOSE) logs --tail=100 -f target-host-2

logs-host3: ## Show logs from host3
	@$(DOCKER_COMPOSE) logs --tail=100 -f target-host-3

status: ## Show status of all containers
	@echo "$(BLUE)Container Status:$(NC)"
	@$(DOCKER_COMPOSE) ps
	@echo ""
	@echo "$(BLUE)Host Connectivity:$(NC)"
	@nc -z 172.28.0.10 22 && echo "host1 (172.28.0.10:22): accessible" || echo "host1 (172.28.0.10:22): not accessible"
	@nc -z 172.28.0.11 22 && echo "host2 (172.28.0.11:22): accessible" || echo "host2 (172.28.0.11:22): not accessible"
	@nc -z 172.28.0.12 22 && echo "host3 (172.28.0.12:22): accessible" || echo "host3 (172.28.0.12:22): not accessible"

# Development targets
shell-host1: ## Open shell in host1 container
	@docker exec -it seaweed-up-host1 bash

shell-host2: ## Open shell in host2 container
	@docker exec -it seaweed-up-host2 bash

shell-host3: ## Open shell in host3 container
	@docker exec -it seaweed-up-host3 bash

# SSH targets (for debugging)
ssh-host1: ## SSH into host1
	@ssh -i .ssh/id_rsa_test -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null root@172.28.0.10

ssh-host2: ## SSH into host2
	@ssh -i .ssh/id_rsa_test -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null root@172.28.0.11

ssh-host3: ## SSH into host3
	@ssh -i .ssh/id_rsa_test -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null root@172.28.0.12

# CI targets
ci-test: ## Run tests in CI environment
	@echo "$(YELLOW)Running CI integration tests...$(NC)"
	@make build
	@make setup
	@make test || (make clean && exit 1)
	@make clean

# Quick development cycle
dev: build setup ## Quick development setup
	@echo "$(GREEN)Development environment ready!$(NC)"
	@echo "Run 'make test' to run integration tests"
	@echo "Run 'make shell-host1' to access host1"
	@echo "Run 'make clean' when done"
